var selecao = document.createElement("div"); selecao.className = "nga-andamentos-selecao";
selecao.innerHTML = '<label><input type="checkbox" id="an-todos"> Selecionar todos</label>';
$("an-tabela").before(selecao);
$("an-todos").addEventListener("change", function () {
  var marcado = this.checked;
  S.lista.forEach(function (l) { if (marcado) delete S.desmarcados[l.id]; else S.desmarcados[l.id] = 1; });
  sec.querySelectorAll("[data-an]").forEach(function (c) { c.checked = marcado; });
  atualizaContagem();
});
$("an-gerar").addEventListener("click", gerarPDF);

function atualizaContagem() {
  var n = selecionadas().length; $("an-gerar").disabled = !n; $("an-info").textContent = " · " + n + " andamento(s) no relatório";
  var todos = $("an-todos"); if (todos) { todos.disabled = !S.lista.length; todos.checked = !!n && n === S.lista.length; todos.indeterminate = n > 0 && n < S.lista.length; }
}
